# Break My Fix finding 2, generated by Tracefix: Env.db_url returns a wrong value.
# Property (issue): env.db_url with extra_options merges them into OPTIONS of the returned config
# Quote: Perhaps they can be passed in a new `extra_options` argument?
# Run it with pytest: it fails for as long as the code breaks this property.

from environ.environ import Env


def test_break_my_fix_2() -> None:
    self_after = Env()
    var = 'DJANGO_ENVIRON_UNSET_TEST_VAR_XYZ'
    default = 'postgres://user:pass@localhost:5432/db'
    extra_options = {'pool': {'min_size': 2, 'max_size': 4, 'timeout': 10}}
    # The property applies to this input: var == 'DJANGO_ENVIRON_UNSET_TEST_VAR_XYZ' and isinstance(extra_options, dict) and len(extra_options) > 0 and isinstance(default, str) and '://' in default and default.split('://')[0] in Env.DB_SCHEMES
    result = self_after.db_url(var=var, default=default, extra_options={'pool': {'min_size': 2, 'max_size': 4, 'timeout': 10}})
    assert (isinstance(result.get('OPTIONS'), dict) and all(k in result['OPTIONS'] and result['OPTIONS'][k] == v for k, v in extra_options.items()))
